//! ⚠️ The exact original member publication error retains every typed field until paid domain publication or retirement.
use semio_framework_job::{OriginalDomainFailure,OriginalDomainProjection,OriginalDomainView as V};
use semio_framework_value::{ValueError,ValueRefusalKind,RetainedCloneProgress,Number};
use store::VcsError as E;
use protocol::{MutationApplyError,MutationMessage,MergePolicy};
#[derive(Debug,semio_framework_value::RetireOwned)]
pub struct OriginalMemberPublicationFailure{pub source:E,pub effects:RetainedCloneProgress,pub receipt_refusal:Option<ValueError>}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"original member failure projection path changed")}
fn kind(e:&E)->&'static str{match e{E::UnknownEdit(_)=>"unknownEdit",E::UnknownChange(_)=>"unknownChange",E::UnknownAlternative(_)=>"unknownAlternative",E::NoCheckpoint=>"noCheckpoint",E::EmptyApply=>"emptyApply",E::MutationApply(_)=>"mutationApply",E::InverseRefused(_)=>"inverseRefused",E::NativeEncoding(_)=>"nativeEncoding",E::NothingToUndo=>"nothingToUndo",E::ForeignEdit(_)=>"foreignEdit",E::NothingToRedo=>"nothingToRedo",E::Serialize(_)=>"serialize",E::Deserialize(_)=>"deserialize",E::Backbone(_)=>"backbone",E::DialectMismatch(_)=>"dialectMismatch",E::MigrationRequired(_)=>"migrationRequired",E::MigrationFailed(_)=>"migrationFailed",E::CompositionCycle(_)=>"compositionCycle",E::OwnershipViolation(_)=>"ownershipViolation",E::ValidationFailed(_)=>"validationFailed",E::CompensationFailed(_)=>"compensationFailed",E::Rejected{..}=>"rejected",E::UnknownConflict(_)=>"unknownConflict",E::Stale{..}=>"stale",E::HistoryShape{..}=>"historyShape",E::TransactionOpen{..}=>"transactionOpen",E::UnknownTransaction(_)=>"unknownTransaction",E::HistoryFull{..}=>"historyFull",E::HistoryReplaying=>"historyReplaying",E::TooLarge{..}=>"tooLarge",E::UnitSpansDocuments{..}=>"unitSpansDocuments"}}
impl OriginalDomainFailure for OriginalMemberPublicationFailure{
 fn domain_code(&self)->&str{"member.publication"}
 fn domain_message(&self)->&str{match payload(&self.source){Node::Text(s)=>s,Node::Value(e)=>&e.message,Node::Apply(e)=>&e.message,_=>"Original member publication refused"}}
 fn domain_retained_progress(&self)->RetainedCloneProgress{self.effects}
}
#[derive(Clone,Copy)]enum Node<'a>{Error(&'a E),Text(&'a str),Value(&'a ValueError),Apply(&'a MutationApplyError),Targets(&'a[String]),Rejected(&'a MergePolicy,&'a[MutationMessage]),Messages(&'a[MutationMessage]),Message(&'a MutationMessage),Number(u64),TextPair(&'static[&'static str;2],&'a str,&'a str),Numbers(&'static[&'static str;2],u64,u64),Null}
fn payload(e:&E)->Node<'_>{match e{
 E::UnknownEdit(s)|E::UnknownChange(s)|E::UnknownAlternative(s)|E::ForeignEdit(s)|E::Serialize(s)|E::Deserialize(s)|E::Backbone(s)|E::DialectMismatch(s)|E::MigrationRequired(s)|E::MigrationFailed(s)|E::CompositionCycle(s)|E::OwnershipViolation(s)|E::ValidationFailed(s)|E::CompensationFailed(s)|E::UnknownConflict(s)|E::UnknownTransaction(s)=>Node::Text(s),
 E::TransactionOpen{transaction_id}=>Node::Text(transaction_id),E::InverseRefused(e)|E::NativeEncoding(e)=>Node::Value(e),E::MutationApply(e)=>Node::Apply(e),E::Rejected{policy,messages}=>Node::Rejected(policy,messages),E::Stale{expected_generation,generation}=>Node::Numbers(&["expectedGeneration","generation"],*expected_generation,*generation),E::HistoryShape{shape,kind}=>Node::TextPair(&["shape","kind"],shape.name(),kind.name()),E::HistoryFull{capacity}=>Node::Number(*capacity as u64),E::TooLarge{rows,capacity}=>Node::Numbers(&["rows","capacity"],*rows as u64,*capacity as u64),E::UnitSpansDocuments{mutation_id,unit}=>Node::TextPair(&["mutationId","unit"],mutation_id,unit),E::NoCheckpoint|E::EmptyApply|E::NothingToUndo|E::NothingToRedo|E::HistoryReplaying=>Node::Null}}
fn child(n:Node<'_>,i:usize)->Result<Node<'_>,ValueError>{Ok(match n{
 Node::Error(e)=>match i{0=>Node::Text(kind(e)),1=>payload(e),_=>return Err(invalid())},Node::Apply(e)=>match i{0=>Node::Text(&e.code),1=>Node::Text(&e.message),2=>Node::Targets(&e.target),_=>return Err(invalid())},Node::Targets(v)=>Node::Text(v.get(i).ok_or_else(invalid)?),Node::Messages(v)=>Node::Message(v.get(i).ok_or_else(invalid)?),Node::Rejected(p,m)=>match i{0=>Node::Text(match p{MergePolicy::LaissezFaire=>"LaissezFaire",MergePolicy::Normal=>"Normal",MergePolicy::Vigilant=>"Vigilant"}),1=>Node::Messages(m),_=>return Err(invalid())},Node::Message(m)=>match i{0=>Node::Text(match m.level{semio_framework_diagnostic::Severity::Info=>"info",semio_framework_diagnostic::Severity::Warning=>"warning",semio_framework_diagnostic::Severity::Error=>"error",semio_framework_diagnostic::Severity::Fatal=>"fatal"}),1=>Node::Text(&m.code.0),2=>Node::Text(&m.message),3=>Node::Targets(&m.target),4=>m.op_index.map_or(Node::Null,|n|Node::Number(n as u64)),_=>return Err(invalid())},Node::TextPair(_,a,b)=>match i{0=>Node::Text(a),1=>Node::Text(b),_=>return Err(invalid())},Node::Numbers(_,a,b)=>match i{0=>Node::Number(a),1=>Node::Number(b),_=>return Err(invalid())},_=>return Err(invalid())})}
fn view<'a>(mut n:Node<'a>,path:&[usize])->Result<V<'a>,ValueError>{for(i,p)in path.iter().enumerate(){if let Node::Value(e)=n{return semio_framework_job::project_original_value_error(e,&path[i..])}n=child(n,*p)?}Ok(match n{Node::Value(e)=>return semio_framework_job::project_original_value_error(e,&[]),Node::Error(_)|Node::Rejected(..)|Node::TextPair(..)|Node::Numbers(..)=>V::IntrinsicObject(2),Node::Apply(_)=>V::IntrinsicObject(3),Node::Message(_)=>V::IntrinsicObject(5),Node::Targets(v)=>V::IntrinsicArray(v.len()),Node::Messages(v)=>V::IntrinsicArray(v.len()),Node::Text(s)=>V::IntrinsicText(s),Node::Number(n)=>V::IntrinsicNumber(Number::UInt(n)),Node::Null=>V::IntrinsicNull})}
fn key<'a>(mut n:Node<'a>,path:&[usize],index:usize)->Result<&'a str,ValueError>{for(i,p)in path.iter().enumerate(){if let Node::Value(e)=n{return semio_framework_job::key_original_value_error(e,&path[i..],index)}n=child(n,*p)?}if let Node::Value(e)=n{return semio_framework_job::key_original_value_error(e,&[],index)}let keys:&[&str]=match n{Node::Error(_)=>&["kind","detail"],Node::Rejected(..)=>&["policy","messages"],Node::Apply(_)=>&["code","message","target"],Node::Message(_)=>&["level","code","message","target","opIndex"],Node::TextPair(k,..)|Node::Numbers(k,..)=>k,_=>return Err(invalid())};keys.get(index).copied().ok_or_else(invalid)}
impl OriginalDomainProjection for OriginalMemberPublicationFailure{
 fn projection_identity(&self)->usize{&self.source as*const E as usize}
 fn projection_view(&self,path:&[usize])->Result<V<'_>,ValueError>{match path{[]=>Ok(V::IntrinsicObject(3)),[0,rest @ ..]=>view(Node::Error(&self.source),rest),[1]=>Ok(V::IntrinsicObject(4)),[1,index]=>Ok(V::IntrinsicNumber(Number::UInt(*[self.effects.copied_items,self.effects.copied_bytes,self.effects.retained_capacity_bytes,self.effects.released_bytes].get(*index).ok_or_else(invalid)?as u64))),[2,rest @ ..]=>match &self.receipt_refusal{Some(e)=>semio_framework_job::project_original_value_error(e,rest),None if rest.is_empty()=>Ok(V::IntrinsicNull),None=>Err(invalid())},_=>Err(invalid())}}
 fn projection_key(&self,path:&[usize],index:usize)->Result<&str,ValueError>{match path{[]=>["source","effects","receiptRefusal"].get(index).copied().ok_or_else(invalid),[0,rest @ ..]=>key(Node::Error(&self.source),rest,index),[1]=>["copiedItems","copiedBytes","retainedCapacityBytes","releasedBytes"].get(index).copied().ok_or_else(invalid),[2,rest @ ..]=>semio_framework_job::key_original_value_error(self.receipt_refusal.as_ref().ok_or_else(invalid)?,rest,index),_=>Err(invalid())}}
}

